import { BookOpen, Users, GraduationCap, DoorOpen, CreditCard } from "lucide-react";

interface StatsHeaderProps {
  coursesCount: number;
  participantsCount: number;
  instructorsCount: number;
  roomsCount: number;
  pendingPayments: number;
}

export function StatsHeader({
  coursesCount,
  participantsCount,
  instructorsCount,
  roomsCount,
  pendingPayments,
}: StatsHeaderProps) {
  const stats = [
    {
      label: "Aktive Kurse",
      value: coursesCount,
      icon: BookOpen,
      accent: false,
    },
    {
      label: "Teilnehmer",
      value: participantsCount,
      icon: Users,
      accent: false,
    },
    {
      label: "Dozenten",
      value: instructorsCount,
      icon: GraduationCap,
      accent: false,
    },
    {
      label: "Raume",
      value: roomsCount,
      icon: DoorOpen,
      accent: false,
    },
    {
      label: "Offene Zahlungen",
      value: pendingPayments,
      icon: CreditCard,
      accent: true,
    },
  ];

  return (
    <div className="bg-gradient-to-br from-primary to-[hsl(260_70%_50%)] px-4 py-6 sm:px-6 sm:py-8">
      <div className="mx-auto max-w-[1400px]">
        <div className="mb-6">
          <h1 className="text-2xl font-800 tracking-tight text-primary-foreground sm:text-3xl">
            KursManager
          </h1>
          <p className="mt-1 text-sm font-300 text-primary-foreground/70">
            Kursverwaltung auf einen Blick
          </p>
        </div>
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-5 lg:gap-4">
          {stats.map((stat) => (
            <div
              key={stat.label}
              className={`rounded-xl px-4 py-3 backdrop-blur-sm transition-all ${
                stat.accent
                  ? "bg-accent/20 border border-accent/30"
                  : "bg-primary-foreground/10 border border-primary-foreground/10"
              }`}
            >
              <div className="flex items-center gap-2">
                <stat.icon className="size-4 text-primary-foreground/70" />
                <span className="text-xs font-500 text-primary-foreground/70 truncate">
                  {stat.label}
                </span>
              </div>
              <p className="mt-1 text-2xl font-700 text-primary-foreground">
                {stat.value}
              </p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import { useState } from "react";
import { format } from "date-fns";
import { de } from "date-fns/locale";
import { Plus, Pencil, Trash2, Search } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription,
} from "@/components/ui/dialog";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { Label } from "@/components/ui/label";
import type { Course, Instructor, Room } from "@/types/app";

interface CoursesTabProps {
  courses: Course[];
  instructors: Instructor[];
  rooms: Room[];
  loading: boolean;
  onAdd: (data: Partial<Course>) => Promise<void>;
  onUpdate: (id: string, data: Partial<Course>) => Promise<void>;
  onDelete: (id: string) => Promise<void>;
}

const emptyCourse = {
  title: "",
  description: "",
  start_date: "",
  end_date: "",
  max_participants: 0,
  price: 0,
  instructor: "",
  room: "",
};

export function CoursesTab({ courses, instructors, rooms, loading, onAdd, onUpdate, onDelete }: CoursesTabProps) {
  const [search, setSearch] = useState("");
  const [dialogOpen, setDialogOpen] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [editing, setEditing] = useState<Course | null>(null);
  const [form, setForm] = useState(emptyCourse);
  const [saving, setSaving] = useState(false);

  const filtered = courses.filter((c) =>
    c.title.toLowerCase().includes(search.toLowerCase()) ||
    c.description.toLowerCase().includes(search.toLowerCase())
  );

  const openAdd = () => {
    setEditing(null);
    setForm(emptyCourse);
    setDialogOpen(true);
  };

  const openEdit = (course: Course) => {
    setEditing(course);
    setForm({
      title: course.title,
      description: course.description,
      start_date: course.start_date,
      end_date: course.end_date,
      max_participants: course.max_participants,
      price: course.price,
      instructor: course.instructor,
      room: course.room,
    });
    setDialogOpen(true);
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      if (editing) {
        await onUpdate(editing.record_id, form);
      } else {
        await onAdd(form);
      }
      setDialogOpen(false);
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (deleteId) {
      await onDelete(deleteId);
      setDeleteId(null);
    }
  };

  const getInstructorName = (id: string) => {
    const inst = instructors.find((i) => i.record_id === id);
    return inst?.name ?? "–";
  };

  const getRoomName = (id: string) => {
    const room = rooms.find((r) => r.record_id === id);
    return room ? `${room.room_name} (${room.building})` : "–";
  };

  const formatDate = (d: string) => {
    if (!d) return "–";
    try {
      return format(new Date(d), "dd. MMM yyyy", { locale: de });
    } catch {
      return d;
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <div className="size-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground" />
          <Input
            placeholder="Kurse durchsuchen..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9"
          />
        </div>
        <Button onClick={openAdd} className="gap-2">
          <Plus className="size-4" />
          Neuer Kurs
        </Button>
      </div>

      {filtered.length === 0 ? (
        <div className="flex flex-col items-center justify-center rounded-xl border border-dashed py-16 text-muted-foreground">
          <p className="text-sm">Noch keine Kurse vorhanden</p>
          <Button variant="outline" className="mt-3 gap-2" onClick={openAdd}>
            <Plus className="size-4" />
            Ersten Kurs anlegen
          </Button>
        </div>
      ) : (
        <div className="rounded-xl border bg-card overflow-hidden">
          <Table>
            <TableHeader>
              <TableRow className="bg-muted/50">
                <TableHead>Titel</TableHead>
                <TableHead className="hidden sm:table-cell">Dozent</TableHead>
                <TableHead className="hidden md:table-cell">Raum</TableHead>
                <TableHead className="hidden lg:table-cell">Zeitraum</TableHead>
                <TableHead className="text-right">Preis</TableHead>
                <TableHead className="hidden sm:table-cell text-right">Max. TN</TableHead>
                <TableHead className="w-[100px]"></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filtered.map((course) => (
                <TableRow key={course.record_id}>
                  <TableCell>
                    <div>
                      <p className="font-600">{course.title}</p>
                      {course.description && (
                        <p className="text-xs text-muted-foreground truncate max-w-[200px]">
                          {course.description}
                        </p>
                      )}
                    </div>
                  </TableCell>
                  <TableCell className="hidden sm:table-cell">
                    <Badge variant="secondary">{getInstructorName(course.instructor)}</Badge>
                  </TableCell>
                  <TableCell className="hidden md:table-cell text-sm">
                    {getRoomName(course.room)}
                  </TableCell>
                  <TableCell className="hidden lg:table-cell text-sm">
                    {formatDate(course.start_date)} – {formatDate(course.end_date)}
                  </TableCell>
                  <TableCell className="text-right font-600">
                    {course.price > 0 ? `${course.price.toFixed(2)} \u20AC` : "–"}
                  </TableCell>
                  <TableCell className="hidden sm:table-cell text-right">
                    {course.max_participants}
                  </TableCell>
                  <TableCell>
                    <div className="flex gap-1 justify-end">
                      <Button variant="ghost" size="icon-sm" onClick={() => openEdit(course)}>
                        <Pencil className="size-3.5" />
                      </Button>
                      <Button variant="ghost" size="icon-sm" onClick={() => setDeleteId(course.record_id)}>
                        <Trash2 className="size-3.5 text-destructive" />
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      )}

      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="sm:max-w-lg">
          <DialogHeader>
            <DialogTitle>{editing ? "Kurs bearbeiten" : "Neuer Kurs"}</DialogTitle>
            <DialogDescription>
              {editing ? "Kursdaten aktualisieren" : "Einen neuen Kurs anlegen"}
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-2">
            <div className="grid gap-2">
              <Label>Titel *</Label>
              <Input value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} />
            </div>
            <div className="grid gap-2">
              <Label>Beschreibung</Label>
              <Input value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="grid gap-2">
                <Label>Startdatum *</Label>
                <Input type="date" value={form.start_date} onChange={(e) => setForm({ ...form, start_date: e.target.value })} />
              </div>
              <div className="grid gap-2">
                <Label>Enddatum *</Label>
                <Input type="date" value={form.end_date} onChange={(e) => setForm({ ...form, end_date: e.target.value })} />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="grid gap-2">
                <Label>Max. Teilnehmer</Label>
                <Input type="number" value={form.max_participants} onChange={(e) => setForm({ ...form, max_participants: Number(e.target.value) })} />
              </div>
              <div className="grid gap-2">
                <Label>Preis (EUR)</Label>
                <Input type="number" step="0.01" value={form.price} onChange={(e) => setForm({ ...form, price: Number(e.target.value) })} />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="grid gap-2">
                <Label>Dozent</Label>
                <Select value={form.instructor} onValueChange={(v) => setForm({ ...form, instructor: v })}>
                  <SelectTrigger className="w-full">
                    <SelectValue placeholder="Auswahlen..." />
                  </SelectTrigger>
                  <SelectContent>
                    {instructors.map((i) => (
                      <SelectItem key={i.record_id} value={i.record_id}>{i.name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="grid gap-2">
                <Label>Raum</Label>
                <Select value={form.room} onValueChange={(v) => setForm({ ...form, room: v })}>
                  <SelectTrigger className="w-full">
                    <SelectValue placeholder="Auswahlen..." />
                  </SelectTrigger>
                  <SelectContent>
                    {rooms.map((r) => (
                      <SelectItem key={r.record_id} value={r.record_id}>{r.room_name} ({r.building})</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDialogOpen(false)}>Abbrechen</Button>
            <Button onClick={handleSave} disabled={saving || !form.title || !form.start_date || !form.end_date}>
              {saving ? "Speichern..." : "Speichern"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <AlertDialog open={!!deleteId} onOpenChange={(open) => !open && setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Kurs loschen?</AlertDialogTitle>
            <AlertDialogDescription>
              Diese Aktion kann nicht ruckgangig gemacht werden.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Abbrechen</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete}>Loschen</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState } from "react";
import { Plus, Pencil, Trash2, Search, Mail, Phone } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription,
} from "@/components/ui/dialog";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Label } from "@/components/ui/label";
import type { Instructor } from "@/types/app";

interface InstructorsTabProps {
  instructors: Instructor[];
  loading: boolean;
  onAdd: (data: Partial<Instructor>) => Promise<void>;
  onUpdate: (id: string, data: Partial<Instructor>) => Promise<void>;
  onDelete: (id: string) => Promise<void>;
}

const emptyForm = { name: "", email: "", phone: "", specialty: "" };

export function InstructorsTab({ instructors, loading, onAdd, onUpdate, onDelete }: InstructorsTabProps) {
  const [search, setSearch] = useState("");
  const [dialogOpen, setDialogOpen] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [editing, setEditing] = useState<Instructor | null>(null);
  const [form, setForm] = useState(emptyForm);
  const [saving, setSaving] = useState(false);

  const filtered = instructors.filter(
    (i) =>
      i.name.toLowerCase().includes(search.toLowerCase()) ||
      i.specialty.toLowerCase().includes(search.toLowerCase())
  );

  const openAdd = () => { setEditing(null); setForm(emptyForm); setDialogOpen(true); };
  const openEdit = (inst: Instructor) => {
    setEditing(inst);
    setForm({ name: inst.name, email: inst.email, phone: inst.phone, specialty: inst.specialty });
    setDialogOpen(true);
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      if (editing) await onUpdate(editing.record_id, form);
      else await onAdd(form);
      setDialogOpen(false);
    } finally { setSaving(false); }
  };

  const handleDelete = async () => {
    if (deleteId) { await onDelete(deleteId); setDeleteId(null); }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <div className="size-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground" />
          <Input placeholder="Dozenten durchsuchen..." value={search} onChange={(e) => setSearch(e.target.value)} className="pl-9" />
        </div>
        <Button onClick={openAdd} className="gap-2">
          <Plus className="size-4" />
          Neuer Dozent
        </Button>
      </div>

      {filtered.length === 0 ? (
        <div className="flex flex-col items-center justify-center rounded-xl border border-dashed py-16 text-muted-foreground">
          <p className="text-sm">Noch keine Dozenten vorhanden</p>
          <Button variant="outline" className="mt-3 gap-2" onClick={openAdd}>
            <Plus className="size-4" />
            Ersten Dozent anlegen
          </Button>
        </div>
      ) : (
        <div className="rounded-xl border bg-card overflow-hidden">
          <Table>
            <TableHeader>
              <TableRow className="bg-muted/50">
                <TableHead>Name</TableHead>
                <TableHead>Fachgebiet</TableHead>
                <TableHead className="hidden sm:table-cell">Kontakt</TableHead>
                <TableHead className="w-[100px]"></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filtered.map((inst) => (
                <TableRow key={inst.record_id}>
                  <TableCell className="font-600">{inst.name}</TableCell>
                  <TableCell>
                    <Badge variant="secondary">{inst.specialty || "–"}</Badge>
                  </TableCell>
                  <TableCell className="hidden sm:table-cell">
                    <div className="flex flex-col gap-0.5 text-xs text-muted-foreground">
                      {inst.email && (
                        <span className="flex items-center gap-1"><Mail className="size-3" />{inst.email}</span>
                      )}
                      {inst.phone && (
                        <span className="flex items-center gap-1"><Phone className="size-3" />{inst.phone}</span>
                      )}
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className="flex gap-1 justify-end">
                      <Button variant="ghost" size="icon-sm" onClick={() => openEdit(inst)}>
                        <Pencil className="size-3.5" />
                      </Button>
                      <Button variant="ghost" size="icon-sm" onClick={() => setDeleteId(inst.record_id)}>
                        <Trash2 className="size-3.5 text-destructive" />
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      )}

      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>{editing ? "Dozent bearbeiten" : "Neuer Dozent"}</DialogTitle>
            <DialogDescription>{editing ? "Dozentendaten aktualisieren" : "Einen neuen Dozenten anlegen"}</DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-2">
            <div className="grid gap-2">
              <Label>Name *</Label>
              <Input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
            </div>
            <div className="grid gap-2">
              <Label>E-Mail</Label>
              <Input type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} />
            </div>
            <div className="grid gap-2">
              <Label>Telefon</Label>
              <Input value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} />
            </div>
            <div className="grid gap-2">
              <Label>Fachgebiet</Label>
              <Input value={form.specialty} onChange={(e) => setForm({ ...form, specialty: e.target.value })} />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDialogOpen(false)}>Abbrechen</Button>
            <Button onClick={handleSave} disabled={saving || !form.name}>{saving ? "Speichern..." : "Speichern"}</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <AlertDialog open={!!deleteId} onOpenChange={(open) => !open && setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Dozent loschen?</AlertDialogTitle>
            <AlertDialogDescription>Diese Aktion kann nicht ruckgangig gemacht werden.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Abbrechen</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete}>Loschen</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState } from "react";
import { format } from "date-fns";
import { de } from "date-fns/locale";
import { Plus, Pencil, Trash2, Search, Mail, Phone } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription,
} from "@/components/ui/dialog";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Label } from "@/components/ui/label";
import type { Participant } from "@/types/app";

interface ParticipantsTabProps {
  participants: Participant[];
  loading: boolean;
  onAdd: (data: Partial<Participant>) => Promise<void>;
  onUpdate: (id: string, data: Partial<Participant>) => Promise<void>;
  onDelete: (id: string) => Promise<void>;
