// Temporary types - will be replaced by generated types from LivingApps
export interface Course {
  record_id: string;
  title: string;
  description: string;
  start_date: string;
  end_date: string;
  max_participants: number;
  price: number;
  instructor: string;
  room: string;
}

export interface Instructor {
  record_id: string;
  name: string;
  email: string;
  phone: string;
  specialty: string;
}

export interface Participant {
  record_id: string;
  name: string;
  email: string;
  phone: string;
  birth_date: string;
}

export interface Room {
  record_id: string;
  room_name: string;
  building: string;
  capacity: number;
}

export interface Enrollment {
  record_id: string;
  participant: string;
  course: string;
  enrollment_date: string;
  paid: boolean;
}

import { useState, useEffect, useCallback } from "react";
import { BookOpen, GraduationCap, Users, DoorOpen, ClipboardList } from "lucide-react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Toaster, toast } from "sonner";
import { StatsHeader } from "@/components/StatsHeader";
import { CoursesTab } from "@/components/CoursesTab";
import { InstructorsTab } from "@/components/InstructorsTab";
import { ParticipantsTab } from "@/components/ParticipantsTab";
import { RoomsTab } from "@/components/RoomsTab";
import { EnrollmentsTab } from "@/components/EnrollmentsTab";
import { LivingAppsService } from "@/services/livingAppsService";
import type { Course, Instructor, Participant, Room, Enrollment } from "@/types/app";

export default function Dashboard() {
  const [courses, setCourses] = useState<Course[]>([]);
  const [instructors, setInstructors] = useState<Instructor[]>([]);
  const [participants, setParticipants] = useState<Participant[]>([]);
  const [rooms, setRooms] = useState<Room[]>([]);
  const [enrollments, setEnrollments] = useState<Enrollment[]>([]);
  const [loading, setLoading] = useState(true);

  const loadAll = useCallback(async () => {
    setLoading(true);
    try {
      const [c, i, p, r, e] = await Promise.all([
        LivingAppsService.getCourses(),
        LivingAppsService.getInstructors(),
        LivingAppsService.getParticipants(),
        LivingAppsService.getRooms(),
        LivingAppsService.getEnrollments(),
      ]);
      setCourses(c);
      setInstructors(i);
      setParticipants(p);
      setRooms(r);
      setEnrollments(e);
    } catch (err) {
      console.error("Failed to load data:", err);
      toast.error("Daten konnten nicht geladen werden");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { loadAll(); }, [loadAll]);

  const pendingPayments = enrollments.filter((e) => !e.paid).length;

  // Course CRUD
  const handleAddCourse = async (data: Partial<Course>) => {
    try {
      const created = await LivingAppsService.createCourse(data);
      setCourses((prev) => [...prev, created]);
      toast.success("Kurs erstellt");
    } catch { toast.error("Fehler beim Erstellen"); }
  };
  const handleUpdateCourse = async (id: string, data: Partial<Course>) => {
    try {
      await LivingAppsService.updateCourse(id, data);
      setCourses(await LivingAppsService.getCourses());
      toast.success("Kurs aktualisiert");
    } catch { toast.error("Fehler beim Aktualisieren"); }
  };
  const handleDeleteCourse = async (id: string) => {
    try {
      await LivingAppsService.deleteCourse(id);
      setCourses((prev) => prev.filter((c) => c.record_id !== id));
      toast.success("Kurs geloscht");
    } catch { toast.error("Fehler beim Loschen"); }
  };

  // Instructor CRUD
  const handleAddInstructor = async (data: Partial<Instructor>) => {
    try {
      const created = await LivingAppsService.createInstructor(data);
      setInstructors((prev) => [...prev, created]);
      toast.success("Dozent erstellt");
    } catch { toast.error("Fehler beim Erstellen"); }
  };
  const handleUpdateInstructor = async (id: string, data: Partial<Instructor>) => {
    try {
      await LivingAppsService.updateInstructor(id, data);
      setInstructors(await LivingAppsService.getInstructors());
      toast.success("Dozent aktualisiert");
    } catch { toast.error("Fehler beim Aktualisieren"); }
  };
  const handleDeleteInstructor = async (id: string) => {
    try {
      await LivingAppsService.deleteInstructor(id);
      setInstructors((prev) => prev.filter((i) => i.record_id !== id));
      toast.success("Dozent geloscht");
    } catch { toast.error("Fehler beim Loschen"); }
  };

  // Participant CRUD
  const handleAddParticipant = async (data: Partial<Participant>) => {
    try {
      const created = await LivingAppsService.createParticipant(data);
      setParticipants((prev) => [...prev, created]);
      toast.success("Teilnehmer erstellt");
    } catch { toast.error("Fehler beim Erstellen"); }
  };
  const handleUpdateParticipant = async (id: string, data: Partial<Participant>) => {
    try {
      await LivingAppsService.updateParticipant(id, data);
      setParticipants(await LivingAppsService.getParticipants());
      toast.success("Teilnehmer aktualisiert");
    } catch { toast.error("Fehler beim Aktualisieren"); }
  };
  const handleDeleteParticipant = async (id: string) => {
    try {
      await LivingAppsService.deleteParticipant(id);
      setParticipants((prev) => prev.filter((p) => p.record_id !== id));
      toast.success("Teilnehmer geloscht");
    } catch { toast.error("Fehler beim Loschen"); }
  };

  // Room CRUD
  const handleAddRoom = async (data: Partial<Room>) => {
    try {
      const created = await LivingAppsService.createRoom(data);
      setRooms((prev) => [...prev, created]);
      toast.success("Raum erstellt");
    } catch { toast.error("Fehler beim Erstellen"); }
  };
  const handleUpdateRoom = async (id: string, data: Partial<Room>) => {
    try {
      await LivingAppsService.updateRoom(id, data);
      setRooms(await LivingAppsService.getRooms());
      toast.success("Raum aktualisiert");
    } catch { toast.error("Fehler beim Aktualisieren"); }
  };
  const handleDeleteRoom = async (id: string) => {
    try {
      await LivingAppsService.deleteRoom(id);
      setRooms((prev) => prev.filter((r) => r.record_id !== id));
      toast.success("Raum geloscht");
    } catch { toast.error("Fehler beim Loschen"); }
  };

  // Enrollment CRUD
  const handleAddEnrollment = async (data: Partial<Enrollment>) => {
    try {
      const created = await LivingAppsService.createEnrollment(data);
      setEnrollments((prev) => [...prev, created]);
      toast.success("Anmeldung erstellt");
    } catch { toast.error("Fehler beim Erstellen"); }
  };
  const handleUpdateEnrollment = async (id: string, data: Partial<Enrollment>) => {
    try {
      await LivingAppsService.updateEnrollment(id, data);
      setEnrollments(await LivingAppsService.getEnrollments());
      toast.success("Anmeldung aktualisiert");
    } catch { toast.error("Fehler beim Aktualisieren"); }
  };
  const handleDeleteEnrollment = async (id: string) => {
    try {
      await LivingAppsService.deleteEnrollment(id);
      setEnrollments((prev) => prev.filter((e) => e.record_id !== id));
      toast.success("Anmeldung geloscht");
    } catch { toast.error("Fehler beim Loschen"); }
  };

  return (
    <div className="min-h-screen bg-background">
      <Toaster position="top-right" richColors />

      <StatsHeader
        coursesCount={courses.length}
        participantsCount={participants.length}
        instructorsCount={instructors.length}
        roomsCount={rooms.length}
        pendingPayments={pendingPayments}
      />

      <div className="mx-auto max-w-[1400px] px-4 py-6 sm:px-6">
        <Tabs defaultValue="courses" className="space-y-4">
          <TabsList className="w-full justify-start overflow-x-auto">
            <TabsTrigger value="courses" className="gap-1.5">
              <BookOpen className="size-4" />
              <span className="hidden sm:inline">Kurse</span>
            </TabsTrigger>
            <TabsTrigger value="instructors" className="gap-1.5">
              <GraduationCap className="size-4" />
              <span className="hidden sm:inline">Dozenten</span>
            </TabsTrigger>
            <TabsTrigger value="participants" className="gap-1.5">
              <Users className="size-4" />
              <span className="hidden sm:inline">Teilnehmer</span>
            </TabsTrigger>
            <TabsTrigger value="rooms" className="gap-1.5">
              <DoorOpen className="size-4" />
              <span className="hidden sm:inline">Raume</span>
            </TabsTrigger>
            <TabsTrigger value="enrollments" className="gap-1.5">
              <ClipboardList className="size-4" />
              <span className="hidden sm:inline">Anmeldungen</span>
            </TabsTrigger>
          </TabsList>

          <TabsContent value="courses">
            <CoursesTab
              courses={courses}
              instructors={instructors}
              rooms={rooms}
              loading={loading}
              onAdd={handleAddCourse}
              onUpdate={handleUpdateCourse}
              onDelete={handleDeleteCourse}
            />
          </TabsContent>

          <TabsContent value="instructors">
            <InstructorsTab
              instructors={instructors}
              loading={loading}
              onAdd={handleAddInstructor}
              onUpdate={handleUpdateInstructor}
              onDelete={handleDeleteInstructor}
            />
          </TabsContent>

          <TabsContent value="participants">
            <ParticipantsTab
              participants={participants}
              loading={loading}
              onAdd={handleAddParticipant}
              onUpdate={handleUpdateParticipant}
              onDelete={handleDeleteParticipant}
            />
          </TabsContent>

          <TabsContent value="rooms">
            <RoomsTab
              rooms={rooms}
              loading={loading}
              onAdd={handleAddRoom}
              onUpdate={handleUpdateRoom}
              onDelete={handleDeleteRoom}
            />
          </TabsContent>

          <TabsContent value="enrollments">
            <EnrollmentsTab
              enrollments={enrollments}
              courses={courses}
              participants={participants}
              loading={loading}
              onAdd={handleAddEnrollment}
              onUpdate={handleUpdateEnrollment}
              onDelete={handleDeleteEnrollment}
            />
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

