              participants={participants}
              loading={loading}
              onAdd={handleAddEnrollment}
              onUpdate={handleUpdateEnrollment}
              onDelete={handleDeleteEnrollment}
            />
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

