    { label: "Offene Zahlungen", value: pendingPayments, icon: CreditCard, accent: true },
  ];

  return (
    <div className="bg-gradient-to-br from-primary to-[hsl(260_70%_50%)] px-4 py-6 sm:px-6 sm:py-8">
