                  <SelectContent>
                    {rooms.map((r) => (
                      <SelectItem key={r.record_id} value={r.record_id}>{r.room_name} ({r.building})</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
